src/field_roamer.c.specie_a_slot:
u8 SpeciesToRoamerIdx(u16 species) {
    switch (species) {
    case SPECIES_RAIKOU:
        return ROAMER_RAIKOU;
    case SPECIES_ENTEI:
        return ROAMER_ENTEI;
    case SPECIES_SUICUNE:
        return ROAMER_SUICUNE;
    default:
        GF_ASSERT(FALSE);
        return ROAMER_MAX;
    }
}
